using System;
using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using Object = UnityEngine.Object;

// 2026-11-10: makes the lawns look fluffy instead of flat.
// 1. The shared lawn material (WillowCourt/Materials/Moss.mat) gets a hand-painted seamless grass tile.
// 2. Small billboard grass tufts are scattered in soft patches over the big walkable lawns.
// Art: Textures/GrassTile.png and Textures/Tuft*.png were generated by Codex (OpenAI image generation)
// on Claude's request, then cropped/cleaned with Python. Re-running rebuilds "20 • Fluffy lawn tufts".
public static class FluffyLawn
{
    private const string Art="Assets/_Project/Art/FluffyLawn/";
    private const string Project="Assets/_Project/";
    private const string GroupName="20 • Fluffy lawn tufts";
    private static readonly string[] Lawns={"Terrace lawn","North garden walkable lawn","South bank","Cliff rim"};
    private static readonly List<string> Log=new List<string>();

    public static float TileScale=.22f;     // texture repeats every 1/TileScale metres
    public static float Spacing=.85f;       // candidate grid spacing (m)
    public static float PatchCut=.53f;      // higher = fewer, smaller patches
    public static float TuftHeight=.4f;    // average tuft height (m)
    public static Color TuftTint=new Color(.8f,.86f,.68f); // pulls the bright tufts towards the lawn colour

    [MenuItem("DG Village/Waterfront/Fluffy lawn")]
    public static void Menu()=>Debug.Log(Build());

    public static string Build()
    {
        Log.Clear();
        if(EditorApplication.isPlaying)throw new InvalidOperationException("Leave Play mode first.");
        var root=GameObject.Find("Willow Court")?.transform;
        if(!root)throw new InvalidOperationException("Open SquareScene first (Willow Court root missing).");
        LawnTexture();
        var old=root.Find(GroupName);if(old)Object.DestroyImmediate(old.gameObject);
        var group=new GameObject(GroupName).transform;group.SetParent(root,false);group.position=Vector3.zero;
        Scatter(root,group);
        EditorSceneManager.MarkSceneDirty(root.gameObject.scene);AssetDatabase.SaveAssets();
        return "Fluffy lawn\n"+string.Join("\n",Log);
    }

    private static Texture2D Texture(string file,bool alpha)
    {
        string path=Art+"Textures/"+file;
        var importer=(TextureImporter)AssetImporter.GetAtPath(path);
        if(!importer)return null;
        importer.textureType=TextureImporterType.Default;importer.alphaIsTransparency=alpha;importer.mipmapEnabled=true;
        importer.wrapMode=alpha?TextureWrapMode.Clamp:TextureWrapMode.Repeat;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=alpha?1:8;
        importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();
        return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
    }

    // ---------- 1. lawn texture ----------
    private static void LawnTexture()
    {
        var tile=Texture("GrassTile.png",false);
        if(!tile){Log.Add("GrassTile.png missing: lawn texture unchanged");return;}
        var moss=AssetDatabase.LoadAssetAtPath<Material>(Project+"Art/WillowCourt/Materials/Moss.mat");
        foreach(var prop in new[]{"_BaseMap","_MainTex"}){moss.SetTexture(prop,tile);moss.SetTextureScale(prop,Vector2.one*TileScale);}
        moss.SetColor("_BaseColor",Color.white);moss.SetFloat("_Smoothness",.04f);
        EditorUtility.SetDirty(moss);
        Log.Add($"Moss.mat → GrassTile.png, repeats every {1/TileScale:F1} m");
    }

    // ---------- 2. tufts ----------
    private static Material TuftMaterial(string name)
    {
        string path=Art+"Materials/"+name+".mat";
        var m=AssetDatabase.LoadAssetAtPath<Material>(path);
        if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(Project+"Materials/Garden/shrub.mat")){name=name};AssetDatabase.CreateAsset(m,path);}
        m.mainTexture=Texture(name+".png",true);m.color=TuftTint;m.SetFloat("_Cutoff",.4f);m.SetFloat("_Smoothness",0);m.SetFloat("_Cull",0);
        m.enableInstancing=true;EditorUtility.SetDirty(m);return m;
    }

    private static void Scatter(Transform root,Transform group)
    {
        var names=AssetDatabase.FindAssets("Tuft t:Texture2D",new[]{Art+"Textures"}).Select(AssetDatabase.GUIDToAssetPath)
            .Select(p=>System.IO.Path.GetFileNameWithoutExtension(p)).Where(n=>n.StartsWith("Tuft")).OrderBy(n=>n).ToArray();
        if(names.Length==0){Log.Add("no Tuft*.png: tufts skipped");return;}
        var mats=names.Select(TuftMaterial).ToArray();
        var quad=SouthBankCoast.BottomQuad();
        var lawns=root.GetComponentsInChildren<Collider>().Where(c=>Lawns.Contains(c.name)&&!(c is BoxCollider&&c.name!="Terrace lawn")).ToList();
        Physics.SyncTransforms();
        var bounds=lawns.Select(c=>c.bounds).Aggregate((a,b)=>{a.Encapsulate(b);return a;});
        var rng=new System.Random(2011);float R()=>(float)rng.NextDouble();
        int placed=0;var counts=new int[names.Length];
        var camFacing=Quaternion.Euler(30,45,0);
        // Paths, plazas and inlays are flat meshes without colliders lying on top of the lawn colliders.
        // Give them temporary colliders on the Ignore Raycast layer so a down-ray can tell "visible paving" from lawn.
        var moss=AssetDatabase.LoadAssetAtPath<Material>(Project+"Art/WillowCourt/Materials/Moss.mat");
        var temps=new List<GameObject>();
        foreach(var mr in root.GetComponentsInChildren<MeshRenderer>()){
            var b=mr.bounds;var mf=mr.GetComponent<MeshFilter>();
            if(!mf||!mf.sharedMesh||mr.transform.IsChildOf(group)||lawns.Any(l=>l.transform==mr.transform))continue;
            if(b.size.y>.3f||b.size.x<.3f||b.size.z<.3f||!b.Intersects(bounds)||mr.sharedMaterials.All(m=>m==moss))continue;
            var g=new GameObject("_paving probe"){hideFlags=HideFlags.HideAndDontSave,layer=2};
            g.transform.SetPositionAndRotation(mr.transform.position,mr.transform.rotation);g.transform.localScale=mr.transform.lossyScale;
            g.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;temps.Add(g);
        }
        Physics.SyncTransforms();
        int paved=0;
        for(float x=bounds.min.x;x<bounds.max.x;x+=Spacing)for(float z=bounds.min.z;z<bounds.max.z;z+=Spacing){
            float px=x+(R()-.5f)*Spacing,pz=z+(R()-.5f)*Spacing;
            // Soft patches from two octaves of Perlin noise (no lone tufts: single ones read as dots).
            float n=.65f*Mathf.PerlinNoise(px*.11f+31,pz*.11f+7)+.35f*Mathf.PerlinNoise(px*.37f+3,pz*.37f+91);
            if(n<PatchCut)continue;
            if(!Physics.Raycast(new Vector3(px,30,pz),Vector3.down,out var hit,60))continue;
            if(!lawns.Contains(hit.collider)||hit.normal.y<.97f)continue;
            if(Physics.Raycast(new Vector3(px,30,pz),Vector3.down,out var top,60,1<<2,QueryTriggerInteraction.Ignore)&&top.point.y>hit.point.y-.05f){paved++;continue;}
            // Keep clear of buildings, planters, benches, fences, walls (anything with a solid collider nearby).
            bool blocked=Physics.OverlapSphere(hit.point+Vector3.up*.45f,.4f).Any(c=>!lawns.Contains(c)&&!c.isTrigger&&!c.name.StartsWith("Invisible"));
            if(blocked)continue;
            // Stay a little inside the invisible cliff walls so tufts don't sit on the very lip.
            if(Physics.OverlapSphere(hit.point+Vector3.up*1f,.35f).Any(c=>c.name.StartsWith("Invisible")))continue;
            int k=rng.Next(names.Length);var tex=(Texture2D)mats[k].mainTexture;
            float h=TuftHeight*(.6f+R()*.5f)*Mathf.Lerp(.75f,1.45f,Mathf.InverseLerp(PatchCut,PatchCut+.2f,n)),w=h*tex.width/tex.height;
            var t=new GameObject(names[k],typeof(MeshFilter),typeof(MeshRenderer)).transform;t.SetParent(group,false);
            t.position=hit.point-camFacing*Vector3.forward*.05f;t.rotation=camFacing;t.localScale=new Vector3(R()<.5f?-w:w,h,1);
            t.GetComponent<MeshFilter>().sharedMesh=quad;
            var r=t.GetComponent<MeshRenderer>();r.sharedMaterial=mats[k];r.shadowCastingMode=ShadowCastingMode.Off;r.lightProbeUsage=LightProbeUsage.Off;
            GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.BatchingStatic);
            placed++;counts[k]++;
        }
        foreach(var g in temps)Object.DestroyImmediate(g);
        Log.Add($"paving probes: {temps.Count} flat meshes, {paved} spots skipped as paved");
        Log.Add($"tufts: {placed} on {lawns.Count} lawn surfaces ({string.Join(", ",names.Select((n,i)=>n+" "+counts[i]))})");
    }
}
